{
  "name": "svelte-stageshow-monorepo",
  "version": "0.2.0",
  "private": true,
  "type": "module",
  "packageManager": "pnpm@10.13.1",
  "scripts": {
    "dev": "pnpm --filter svelte-stageshow build && pnpm --filter web dev",
    "build": "pnpm --filter svelte-stageshow build && pnpm --filter web build",
    "check": "pnpm --filter svelte-stageshow check && pnpm --filter web check",
    "film": "node scripts/film.mjs",
    "pack:lib": "pnpm --filter svelte-stageshow pack:tarball"
  },
  "devDependencies": {
    "playwright-core": "1.56.1"
  }
}

{
  "name": "web",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "scripts": {
    "dev": "vite --host 127.0.0.1 --port 5173",
    "build": "vite build && node scripts/prerender-scenes.mjs && node scripts/rewrite-origin.mjs",
    "preview": "vite preview --host 127.0.0.1 --port 4173",
    "check": "svelte-check --tsconfig ./tsconfig.json --fail-on-warnings"
  },
  "dependencies": {
    "sv-agentation": "^0.4.0",
    "svelte": "^5.39.0",
    "svelte-stageshow": "workspace:*"
  },
  "devDependencies": {
    "@sveltejs/vite-plugin-svelte": "^6.0.0",
    "@types/node": "^24.0.0",
    "svelte-check": "^4.3.0",
    "typescript": "^5.9.0",
    "vite": "^7.1.0"
  }
}

import { mount } from 'svelte'
import App from './App.svelte'
import 'svelte-stageshow/style.css'
import './app.css'
import './gallery-dark.css'

const target = document.getElementById('app')
if (!target) throw new Error('#app not found')

const app = mount(App, { target })

export default app

